import json,numpy as np
from PIL import Image
name='lower2';m=json.load(open(f'/app/output/{name}/meta.json'));cam='oblique';K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl'])@np.diag([1,-1,-1,1]);d=np.load(f'/app/output/{name}/depth_{cam}.npy')[-1].astype(float);a=np.array(Image.open(f'/app/output/{name}/last/{cam}.jpg')).astype(float);R,G,B=a[:,:,0],a[:,:,1],a[:,:,2];yy,xx=np.indices(d.shape);P=np.stack([(xx-K[0,2])*d/K[0,0],(yy-K[1,2])*d/K[1,1],d,np.ones_like(d)],-1)@T.T;X=P[:,:,:3]
hand=(R>190)&(G>190)&(B>190)&(d<1.22)&(xx>140)&(xx<185)&(yy>85)&(yy<132)&(X[:,:,2]>.54)
obj=(R<160)&(G<160)&(B<160)&(np.max(a,axis=2)-np.min(a,axis=2)<35)&(d<1.22)&(xx>150)&(xx<195)&(yy>125)&(yy<160)&(X[:,:,2]>.54)
pts=X[hand];xy=np.array([-.065,.028]);dist=np.linalg.norm(pts[:,:2]-xy,axis=1);print('hand nearest',[(np.round(pts[i],3).tolist(),round(dist[i],3)) for i in np.argsort(dist)[:5]])
pts=X[obj];print('obj',len(pts),np.round(np.percentile(pts,[10,50,90],axis=0),3))
PY"});
